#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include "cJSON.h"
#include "lodepng.h"

static char *read_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "cannot open %s\n", path); exit(1); }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char*)malloc(sz + 1);
    fread(buf, 1, sz, f);
    buf[sz] = '\0';
    fclose(f);
    return buf;
}

static double *parse_vec(cJSON *arr, int *nout) {
    int n = cJSON_GetArraySize(arr);
    double *v = (double*)malloc(sizeof(double) * n);
    for (int i = 0; i < n; i++) {
        cJSON *it = cJSON_GetArrayItem(arr, i);
        v[i] = it->valuedouble;
    }
    if (nout) *nout = n;
    return v;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        fprintf(stderr, "usage: %s weights.json image.png\n", argv[0]);
        return 1;
    }
    const char *weights_path = argv[1];
    const char *img_path = argv[2];

    char *json_text = read_file(weights_path);
    cJSON *root = cJSON_Parse(json_text);
    if (!root) { fprintf(stderr, "bad json\n"); return 1; }

    int input_dim = cJSON_GetObjectItem(root, "input_dim")->valueint;
    int hidden_dim = cJSON_GetObjectItem(root, "hidden_dim")->valueint;
    int num_classes = cJSON_GetObjectItem(root, "num_classes")->valueint;
    (void)hidden_dim;

    cJSON *layers = cJSON_GetObjectItem(root, "layers");
    int nlayers = cJSON_GetArraySize(layers);

    int *rows = (int*)malloc(sizeof(int)*nlayers);
    int *cols = (int*)malloc(sizeof(int)*nlayers);
    double **W = (double**)malloc(sizeof(double*)*nlayers);
    double **B = (double**)malloc(sizeof(double*)*nlayers);
    for (int l = 0; l < nlayers; l++) {
        cJSON *layer = cJSON_GetArrayItem(layers, l);
        rows[l] = cJSON_GetObjectItem(layer, "rows")->valueint;
        cols[l] = cJSON_GetObjectItem(layer, "cols")->valueint;
        W[l] = parse_vec(cJSON_GetObjectItem(layer, "w"), NULL);
        B[l] = parse_vec(cJSON_GetObjectItem(layer, "b"), NULL);
    }

    unsigned char *img = NULL;
    unsigned w, h;
    unsigned err = lodepng_decode32_file(&img, &w, &h, img_path);
    if (err) { fprintf(stderr, "png error %u\n", err); return 1; }
    if ((int)(w*h) != input_dim) {
        fprintf(stderr, "image size %ux%u != %d\n", w, h, input_dim);
        return 1;
    }

    double *x = (double*)malloc(sizeof(double)*input_dim);
    for (int p = 0; p < input_dim; p++) {
        unsigned char r = img[p*4];
        x[p] = (double)r / 255.0;
    }

    double *y = NULL;
    for (int l = 0; l < nlayers; l++) {
        int r = rows[l], c = cols[l];
        y = (double*)malloc(sizeof(double)*r);
        for (int i = 0; i < r; i++) {
            double s = B[l][i];
            double *wr = W[l] + (size_t)i * c;
            for (int j = 0; j < c; j++) s += wr[j] * x[j];
            if (l != nlayers - 1) { if (s < 0) s = 0; }
            y[i] = s;
        }
        free(x);
        x = y;
    }

    int best = 0;
    double bestv = x[0];
    for (int i = 1; i < num_classes; i++) {
        if (x[i] > bestv) { bestv = x[i]; best = i; }
    }

    printf("%d\n", best);

    FILE *pf = fopen("/app/prediction.txt", "w");
    if (pf) { fprintf(pf, "%d\n", best); fclose(pf); }

    free(img);
    free(json_text);
    return 0;
}
EOF
